def _data():
    raw = zlib.decompress(base64.b85decode(PACKED.encode("ascii")))
    if hashlib.sha256(raw).hexdigest() != EXPECTED_SHA256:
        raise RuntimeError("AP History 15-41 payload checksum mismatch")
    return json.loads(raw.decode("utf-8"))


def _values_for(table, values):
    return {k: v for k, v in values.items() if k in table.c}


def upgrade():
    bind = op.get_bind()
    if bind.dialect.name == "postgresql":
        bind.execute(sa.text("SELECT pg_advisory_xact_lock(154120261018)"))
    meta = sa.MetaData()
    subjects = sa.Table("subjects", meta, autoload_with=bind)
    legacy_chapters = sa.Table("chapters", meta, autoload_with=bind)
    notes = sa.Table("notes", meta, autoload_with=bind)
    questions = sa.Table("questions", meta, autoload_with=bind)
    units = sa.Table("syllabus_units", meta, autoload_with=bind)
    canonical = sa.Table("syllabus_chapters", meta, autoload_with=bind)
    subtopics = sa.Table("syllabus_subtopics", meta, autoload_with=bind)

    sid = bind.execute(sa.select(subjects.c.id).where(subjects.c.slug == "ap_history")).scalar_one()
    data = _data()

    # Keep an in-database, transactionally consistent recovery snapshot. This
    # migration replaces only AP History chapters 15-41 and their linked rows.
    if bind.dialect.name == "postgresql":
        bind.execute(sa.text("""
            CREATE TABLE IF NOT EXISTS ap_history_15_41_backup_20261018 (
                table_name TEXT NOT NULL, row_data JSONB NOT NULL
            )
        """))
        have_backup = bind.execute(sa.text(
            "SELECT COUNT(*) FROM ap_history_15_41_backup_20261018"
        )).scalar_one()
    else:
        have_backup = 1
    if bind.dialect.name == "postgresql" and have_backup == 0:
        bind.execute(sa.text("""
            INSERT INTO ap_history_15_41_backup_20261018(table_name,row_data)
            SELECT 'chapters',to_jsonb(c) FROM chapters c
             WHERE c.subject_id=:sid AND c.chapter_num BETWEEN 15 AND 41
        """), {"sid": sid})
        bind.execute(sa.text("""
            INSERT INTO ap_history_15_41_backup_20261018(table_name,row_data)
            SELECT 'notes',to_jsonb(n) FROM notes n JOIN chapters c ON c.id=n.chapter_id
             WHERE c.subject_id=:sid AND c.chapter_num BETWEEN 15 AND 41
        """), {"sid": sid})
        bind.execute(sa.text("""
            INSERT INTO ap_history_15_41_backup_20261018(table_name,row_data)
            SELECT 'questions',to_jsonb(q) FROM questions q
             WHERE q.subject_id=:sid AND (
                q.chapter_id IN (SELECT id FROM chapters WHERE subject_id=:sid AND chapter_num BETWEEN 15 AND 41)
                OR q.syllabus_chapter_id IN (SELECT id FROM syllabus_chapters WHERE subject_id=:sid AND chapter_num BETWEEN 15 AND 41)
                OR q.note_target_slug ~ '^u[3-5]-c(1[5-9]|2[0-9]|3[0-9]|4[01])-'
             )
        """), {"sid": sid})
        bind.execute(sa.text("""
            INSERT INTO ap_history_15_41_backup_20261018(table_name,row_data)
            SELECT 'syllabus_chapters',to_jsonb(c) FROM syllabus_chapters c
             WHERE c.subject_id=:sid AND c.chapter_num BETWEEN 15 AND 41
        """), {"sid": sid})
        bind.execute(sa.text("""
            INSERT INTO ap_history_15_41_backup_20261018(table_name,row_data)
            SELECT 'syllabus_subtopics',to_jsonb(s) FROM syllabus_subtopics s
             WHERE s.chapter_id IN (SELECT id FROM syllabus_chapters WHERE subject_id=:sid AND chapter_num BETWEEN 15 AND 41)
        """), {"sid": sid})

    target_legacy = sa.select(legacy_chapters.c.id).where(
        legacy_chapters.c.subject_id == sid,
        legacy_chapters.c.chapter_num.between(15, 41),
    )
    target_canonical = sa.select(canonical.c.id).where(
        canonical.c.subject_id == sid,
        canonical.c.chapter_num.between(15, 41),
    )
    prefixes = tuple(ch["slug"] + "-%" for ch in data["chapters"])
    q_filter = sa.or_(
        questions.c.chapter_id.in_(target_legacy),
        questions.c.syllabus_chapter_id.in_(target_canonical),
        *[questions.c.note_target_slug.like(p) for p in prefixes],
    )
    bind.execute(questions.delete().where(questions.c.subject_id == sid, q_filter))
    bind.execute(notes.delete().where(notes.c.chapter_id.in_(target_legacy)))

    unit_ids = {n: bind.execute(sa.select(units.c.id).where(
        units.c.subject_id == sid, units.c.unit_num == n)).scalar_one() for n in (3,4,5)}
    canonical_ids = {}
    legacy_ids = {}
    now = datetime.utcnow()
    for ch in data["chapters"]:
        n = ch["chapter_num"]
        legacy_id = bind.execute(sa.select(legacy_chapters.c.id).where(
            legacy_chapters.c.subject_id == sid, legacy_chapters.c.chapter_num == n)).scalar_one_or_none()
        legacy_values = dict(subject_id=sid, chapter_num=n, title_en=ch["title_en"], title_te=ch["title_te"],
                             est_read_minutes=ch["est_read_minutes"] or 20)
        if legacy_id is None:
            legacy_id = bind.execute(legacy_chapters.insert().values(**legacy_values).returning(legacy_chapters.c.id)).scalar_one()
        else:
            bind.execute(legacy_chapters.update().where(legacy_chapters.c.id == legacy_id).values(**legacy_values))
        legacy_ids[n] = legacy_id

        canonical_id = bind.execute(sa.select(canonical.c.id).where(
            canonical.c.subject_id == sid, canonical.c.chapter_num == n)).scalar_one_or_none()
        canonical_values = dict(subject_id=sid, unit_id=unit_ids[ch["unit_num"]], chapter_num=n, slug=ch["slug"],
                                title_en=ch["title_en"], title_te=ch["title_te"], classification="direct",
                                supplementary_type=None, sort_order=n)
        if canonical_id is None:
            canonical_id = bind.execute(canonical.insert().values(**canonical_values).returning(canonical.c.id)).scalar_one()
        else:
            bind.execute(canonical.update().where(canonical.c.id == canonical_id).values(**canonical_values))
        canonical_ids[n] = canonical_id

        bind.execute(subtopics.delete().where(subtopics.c.chapter_id == canonical_id))
        bind.execute(subtopics.insert().values(chapter_id=canonical_id, slug=ch["slug"] + "-complete",
                                               subtopic_en="Complete chapter", subtopic_te="పూర్తి అధ్యాయం", sort_order=1))
        for note in ch["notes"]:
            bind.execute(notes.insert().values(**_values_for(notes, dict(chapter_id=legacy_id, **note))))

    keys = ("a", "b", "c", "d")
    inserted = {n: 0 for n in range(15, 42)}
    for q in data["questions"]:
        n = q["chapter_num"]
        trace = q.get("source_trace")
        try:
            trace = json.loads(trace) if isinstance(trace, str) and trace.strip().startswith(("{", "[")) else {"original_notes": trace}
        except Exception:
            trace = {"original_notes": trace}
        values = dict(
            subject_id=sid, chapter_id=legacy_ids[n], source_type="chapter", pyq_year=None, pyq_paper=None,
            difficulty=q["difficulty"], question_en=q["question_en"], question_te=q["question_te"],
            options_en=q["options_en"], options_te=q["options_te"], correct_answer=q["correct_answer"],
            explanation_en=q["explanation_en"], explanation_te=q["explanation_te"], passage_id=None,
            created_at=now, updated_at=now, syllabus_chapter_id=canonical_ids[n], subtopic_id=None,
            secondary_tags={"chapter": n}, source=q["source"][:24], source_file="AP History Chapters 15-41 audited bank",
            source_qid=q["id"], source_chapter=str(n), qtype=q["qtype"][:24], review_status="author_reviewed",
            batch_id=BATCH, content_hash=hashlib.md5((q["id"] + q["question_te"]).encode("utf-8")).hexdigest(),
            collection_id=None, note_target_slug=next(ch["slug"] for ch in data["chapters"] if ch["chapter_num"] == n) + "-main",
            source_trace=trace,
        )
        values["q_hash"] = hashlib.md5((q["question_te"] + json.dumps(q["options_te"], ensure_ascii=False, sort_keys=True)).encode("utf-8")).hexdigest()
        bind.execute(questions.insert().values(**_values_for(questions, values)))
        inserted[n] += 1

    if inserted != {int(k): v for k, v in EXPECTED_COUNTS.items()}:
        raise RuntimeError(f"Inserted count mismatch: {inserted}")
    total = bind.execute(sa.select(sa.func.count()).select_from(questions).where(questions.c.batch_id == BATCH)).scalar_one()
    if total != 4410:
        raise RuntimeError(f"Expected 4410 deployed AP History questions, got {total}")


def downgrade():
    raise RuntimeError(
        "Automatic downgrade is intentionally disabled. The pre-change rows are preserved in "
        "ap_history_15_41_backup_20261018; restore them with a reviewed recovery migration."
    )
